inner join opt_order_type_config tc on tc.id = c.order_type_config_id
left join ord_dis_deliv_request od on o.request_order_id = od.id
left join ord_dis_order_distribution_rel dr on dr.order_id = o.id
left join ord_dis_order_distribution d on d.id = dr.distribution_order_id


        and o.order_no = #{orderNo}


        and o.source_code = #{sourceCode}


        and o.store_code = #{storeCode}


        and o.order_status_code = #{orderStatusCode}


        and c.truncation_date_time between #{beginAcceptDate} and #{endAcceptDate}


        and tc.order_type_code = #{orderTypeCode}


        and tc.order_type_code in

            #{item}



        and d.distribution_order_no = #{distributionOrderNo}


        and o.creator like concat('%', #{creator}, '%')


        and o.create_time = #{createTime}


        and o.is_delete = #{isDelete}


        and o.store_code in

            #{item}



        and exists (select d.order_id from ord_dis_order_detail d
        where d.order_id = o.id
        and d.goods_code = #{goodsCode})


        and o.biz_org_code = #{bizOrgCode,jdbcType=VARCHAR}


        and od.request_order_no = #{requestOrderNo}


        and o.order_amount <= #{payableAmount}


        and o.order_amount >= #{payableAmount}


order by o.id desc

select o.id,o.order_cycle_id,o.store_code,o.order_no,o.order_status_code,o.order_amount,o.preferential_amount,o.source_code, o.cut_off_time,o.org_code,o.creator,o.create_time,o.updater,o.update_time,o.is_delete,c.truncation_date_time,od.request_order_no, od.id requestOrderId,tc.order_type_code,tc.order_type_name,o.submitter,o.sumbit_time,o.discount_amount,o.order_identification from ord_dis_order o inner join ord_dis_order_cycle c on c.id = o.order_cycle_id inner join opt_order_type_config tc on tc.id = c.order_type_config_id left join ord_dis_deliv_request od on o.request_order_id = od.id
and o.id = #{orderId}
and o.biz_org_code = #{bizOrgCode,jdbcType=VARCHAR}
